package com.playerindicatorsplus;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(PlayerIndicatorsPlusConfig.GROUP)
public interface PlayerIndicatorsPlusConfig extends Config
{
	String GROUP = "player-indicators-plus";

	@ConfigSection(
		name = "Highlight options",
		description = "Toggle highlighted players by type and choose their colors",
		position = 99
	)
	String highlightSection = "highlightOptions";

	enum HighlightSetting
	{
		DISABLED,
		ENABLED
	}

	@ConfigItem(
		position = 0,
		keyName = "showPlayerNames",
		name = "Player names",
		description = "Display player names above characters"
	)
	default boolean showPlayerNames()
	{
		return true;
	}

	@ConfigItem(
		position = 1,
		keyName = "colorWildernessNames",
		name = "Display colored names in Wilderness",
		description = "Use the separate Wilderness/PvP color for other players. When disabled, the safe-area color is used"
	)
	default boolean colorWildernessNames()
	{
		return true;
	}

	@ConfigItem(
		position = 0,
		keyName = "highlightOwnPlayer",
		name = "Highlight own player",
		description = "Configures whether your own player name is displayed",
		section = highlightSection
	)
	default HighlightSetting highlightOwnPlayer()
	{
		return HighlightSetting.DISABLED;
	}

	@ConfigItem(
		position = 1,
		keyName = "ownPlayerColor",
		name = "Own player",
		description = "Color of your own player name",
		section = highlightSection
	)
	default Color ownPlayerColor()
	{
		return new Color(0, 184, 212);
	}

	@ConfigItem(
		position = 2,
		keyName = "highlightPartyMembers",
		name = "Highlight party members",
		description = "Use a separate color for members of your current RuneLite party, including Party Hub parties",
		section = highlightSection
	)
	default HighlightSetting highlightPartyMembers()
	{
		return HighlightSetting.ENABLED;
	}

	@ConfigItem(
		position = 3,
		keyName = "partyMemberColor",
		name = "Party member",
		description = "Color of party members; takes priority over friend, clan, team, and combat-zone colors",
		section = highlightSection
	)
	default Color partyMemberColor()
	{
		return new Color(234, 123, 91);
	}

	@ConfigItem(
		position = 4,
		keyName = "highlightFriends",
		name = "Highlight friends",
		description = "Use a separate color for friends",
		section = highlightSection
	)
	default HighlightSetting highlightFriends()
	{
		return HighlightSetting.ENABLED;
	}

	@ConfigItem(
		position = 5,
		keyName = "friendColor",
		name = "Friend",
		description = "Color of friend names",
		section = highlightSection
	)
	default Color friendColor()
	{
		return new Color(0, 200, 83);
	}

	@ConfigItem(
		position = 6,
		keyName = "highlightFriendsCombatZones",
		name = "Highlight friends - Combat Zones",
		description = "Use a separate color for friends who are inside Wilderness or PvP combat zones",
		section = highlightSection
	)
	default HighlightSetting highlightFriendsCombatZones()
	{
		return HighlightSetting.ENABLED;
	}

	@ConfigItem(
		position = 7,
		keyName = "friendsCombatZonesColor",
		name = "Friends - Combat Zones",
		description = "Color of friend names while those friends are inside combat zones",
		section = highlightSection
	)
	default Color friendsCombatZonesColor()
	{
		return new Color(255, 140, 0);
	}

	@ConfigItem(
		position = 8,
		keyName = "highlightFriendsChat",
		name = "Highlight friends chat members",
		description = "Use a separate color for friends chat members",
		section = highlightSection
	)
	default HighlightSetting highlightFriendsChat()
	{
		return HighlightSetting.ENABLED;
	}

	@ConfigItem(
		position = 9,
		keyName = "friendsChatColor",
		name = "Friends chat",
		description = "Color of friends chat member names",
		section = highlightSection
	)
	default Color friendsChatColor()
	{
		return new Color(170, 0, 255);
	}

	@ConfigItem(
		position = 10,
		keyName = "highlightTeamMembers",
		name = "Highlight team members",
		description = "Use a separate color for players on your team",
		section = highlightSection
	)
	default HighlightSetting highlightTeamMembers()
	{
		return HighlightSetting.ENABLED;
	}

	@ConfigItem(
		position = 11,
		keyName = "teamMemberColor",
		name = "Team member",
		description = "Color of team member names",
		section = highlightSection
	)
	default Color teamMemberColor()
	{
		return new Color(19, 110, 247);
	}

	@ConfigItem(
		position = 12,
		keyName = "highlightClanMembers",
		name = "Highlight clan members",
		description = "Use a separate color for clan members",
		section = highlightSection
	)
	default HighlightSetting highlightClanMembers()
	{
		return HighlightSetting.ENABLED;
	}

	@ConfigItem(
		position = 13,
		keyName = "clanMemberColor",
		name = "Clan member",
		description = "Color of clan member names",
		section = highlightSection
	)
	default Color clanMemberColor()
	{
		return new Color(36, 15, 171);
	}

	@ConfigItem(
		position = 14,
		keyName = "highlightOthers",
		name = "Highlight others",
		description = "Display players who do not use an enabled category color",
		section = highlightSection
	)
	default HighlightSetting highlightOthers()
	{
		return HighlightSetting.ENABLED;
	}

	@ConfigItem(
		position = 15,
		keyName = "safeAreaNameColor",
		name = "Others - Safe Areas",
		description = "Color of other player names in safe areas",
		section = highlightSection
	)
	default Color safeAreaNameColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		position = 16,
		keyName = "wildernessNameColor",
		name = "Others - Combat Zones",
		description = "Color of other player names in Wilderness and PvP combat zones",
		section = highlightSection
	)
	default Color wildernessNameColor()
	{
		return Color.RED;
	}

	@ConfigItem(
		position = 2,
		keyName = "drawPlayerTiles",
		name = "Draw tiles under players",
		description = "Draw a colored tile underneath highlighted players"
	)
	default boolean drawTiles()
	{
		return false;
	}

	@ConfigItem(
		position = 3,
		keyName = "playerNamePosition",
		name = "Name position",
		description = "Choose where player names are drawn, or disable overhead names"
	)
	default PlayerNameLocation playerNamePosition()
	{
		return PlayerNameLocation.ABOVE_HEAD;
	}

	@ConfigItem(
		position = 4,
		keyName = "drawMinimapNames",
		name = "Draw names on minimap",
		description = "Draw highlighted player names on the minimap"
	)
	default boolean drawMinimapNames()
	{
		return false;
	}

	@ConfigItem(
		position = 5,
		keyName = "colorPlayerMenu",
		name = "Colorize player menu",
		description = "Color player names in the right-click menu"
	)
	default boolean colorPlayerMenu()
	{
		return true;
	}

	@ConfigItem(
		position = 6,
		keyName = "friendsChatMenuIcons",
		name = "Show friends chat ranks",
		description = "Show friends chat rank icons next to player names and in the right-click menu"
	)
	default boolean showFriendsChatRanks()
	{
		return true;
	}

	@ConfigItem(
		position = 7,
		keyName = "clanChatMenuIcons",
		name = "Show clan chat ranks",
		description = "Show clan rank icons next to player names and in the right-click menu"
	)
	default boolean showClanChatRanks()
	{
		return true;
	}
}

package com.playerindicatorsplus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.Text;

@Singleton
class PlayerIndicatorsPlusMinimapOverlay extends Overlay
{
	private final Client client;
	private final PlayerIndicatorsPlusConfig config;
	private final PlayerIndicatorsPlusOverlay playerNamesOverlay;

	@Inject
	private PlayerIndicatorsPlusMinimapOverlay(Client client, PlayerIndicatorsPlusConfig config,
		PlayerIndicatorsPlusOverlay playerNamesOverlay)
	{
		this.client = client;
		this.config = config;
		this.playerNamesOverlay = playerNamesOverlay;
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN ||
			!config.showPlayerNames() || !config.drawMinimapNames())
		{
			return null;
		}

		WorldView topLevelWorldView = client.getTopLevelWorldView();
		if (topLevelWorldView == null)
		{
			return null;
		}

		int insideWilderness = client.getVarbitValue(VarbitID.INSIDE_WILDERNESS);
		int insidePvpArea = client.getVarbitValue(VarbitID.PVP_AREA_CLIENT);
		renderWorldView(graphics, topLevelWorldView, insideWilderness, insidePvpArea);
		for (WorldView worldView : topLevelWorldView.worldViews())
		{
			renderWorldView(graphics, worldView, insideWilderness, insidePvpArea);
		}

		return null;
	}

	private void renderWorldView(Graphics2D graphics, WorldView worldView,
		int insideWilderness, int insidePvpArea)
	{
		if (worldView == null)
		{
			return;
		}

		for (Player player : worldView.players())
		{
			if (player == null || player.getName() == null)
			{
				continue;
			}

			LocalPoint localPoint = player.getLocalLocation();
			if (localPoint == null || !worldView.contains(localPoint))
			{
				continue;
			}

			Color color = playerNamesOverlay.getPlayerColor(player, insideWilderness, insidePvpArea);
			Point minimapLocation = player.getMinimapLocation();
			if (color != null && minimapLocation != null)
			{
				OverlayUtil.renderTextLocation(
					graphics, minimapLocation, Text.sanitize(player.getName()), color);
			}
		}
	}
}

package com.playerindicatorsplus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.FriendsChatMember;
import net.runelite.api.FriendsChatRank;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.party.PartyService;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.Text;

@Singleton
class PlayerIndicatorsPlusOverlay extends Overlay
{
	private static final int OVERHEAD_TEXT_MARGIN = 40;
	private static final int HORIZONTAL_TEXT_MARGIN = 10;
	private static final int WILDERNESS_WEST_X = 2944;
	private static final int WILDERNESS_EAST_X = 3391;
	private static final int WILDERNESS_SOUTH_Y = 3520;
	private static final int WILDERNESS_NORTH_Y = 3967;
	private static final int WILDERNESS_BOUNDARY_VIEW_DISTANCE = 104;

	private final Client client;
	private final PlayerIndicatorsPlusConfig config;
	private final ChatIconManager chatIconManager;
	private final PartyService partyService;

	@Inject
	PlayerIndicatorsPlusOverlay(Client client, PlayerIndicatorsPlusConfig config,
		ChatIconManager chatIconManager, PartyService partyService)
	{
		this.client = client;
		this.config = config;
		this.chatIconManager = chatIconManager;
		this.partyService = partyService;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		PlayerNameLocation nameLocation = config.playerNamePosition();
		if (client.getGameState() != GameState.LOGGED_IN ||
			!config.showPlayerNames() || nameLocation == PlayerNameLocation.DISABLED)
		{
			return null;
		}

		WorldView topLevelWorldView = client.getTopLevelWorldView();
		if (topLevelWorldView == null)
		{
			return null;
		}

		int insideWilderness = client.getVarbitValue(VarbitID.INSIDE_WILDERNESS);
		int insidePvpArea = client.getVarbitValue(VarbitID.PVP_AREA_CLIENT);
		renderWorldView(graphics, topLevelWorldView, insideWilderness, insidePvpArea, nameLocation);
		for (WorldView worldView : topLevelWorldView.worldViews())
		{
			renderWorldView(graphics, worldView, insideWilderness, insidePvpArea, nameLocation);
		}

		return null;
	}

	static boolean isPvpZone(int insideWilderness, int insidePvpArea)
	{
		return insideWilderness == 1 || insidePvpArea == 1;
	}

	static Color selectNameColor(boolean inPvpZone, boolean colorWildernessNames,
		Color safeAreaColor, Color wildernessColor)
	{
		return inPvpZone && colorWildernessNames ? wildernessColor : safeAreaColor;
	}

	static boolean isMainWildernessSurface(int worldX, int worldY, int plane)
	{
		return plane >= 0 && plane <= 3 &&
			worldX >= WILDERNESS_WEST_X && worldX <= WILDERNESS_EAST_X &&
			worldY >= WILDERNESS_SOUTH_Y && worldY <= WILDERNESS_NORTH_Y;
	}

	static boolean isImmediatelySouthOfWildernessLine(int worldX, int worldY, int plane)
	{
		return plane >= 0 && plane <= 3 &&
			worldX >= WILDERNESS_WEST_X && worldX <= WILDERNESS_EAST_X &&
			worldY >= WILDERNESS_SOUTH_Y - WILDERNESS_BOUNDARY_VIEW_DISTANCE &&
			worldY < WILDERNESS_SOUTH_Y;
	}

	static boolean isPlayerInPvpZone(int worldX, int worldY, int plane,
		int insideWilderness, int insidePvpArea)
	{
		if (isMainWildernessSurface(worldX, worldY, plane))
		{
			return true;
		}

		if (isImmediatelySouthOfWildernessLine(worldX, worldY, plane))
		{
			return false;
		}

		// Caves, instances, and non-Wilderness PvP areas do not share the surface
		// boundary, so use the client PvP state for those locations.
		return isPvpZone(insideWilderness, insidePvpArea);
	}

	private void renderWorldView(Graphics2D graphics, WorldView worldView,
		int insideWilderness, int insidePvpArea, PlayerNameLocation nameLocation)
	{
		if (worldView == null)
		{
			return;
		}

		for (Player player : worldView.players())
		{
			if (player == null || player.getName() == null)
			{
				continue;
			}

			LocalPoint localPoint = player.getLocalLocation();
			if (localPoint == null || !worldView.contains(localPoint))
			{
				continue;
			}

			Color playerColor = getPlayerColor(player, insideWilderness, insidePvpArea);
			if (playerColor != null)
			{
				renderPlayerName(graphics, player, playerColor, nameLocation);
			}
		}
	}

	Color getPlayerColor(Player player, int insideWilderness, int insidePvpArea)
	{
		WorldPoint worldPoint = player.getWorldLocation();
		boolean playerInPvpZone = worldPoint == null
			? isPvpZone(insideWilderness, insidePvpArea)
			: isPlayerInPvpZone(
				worldPoint.getX(),
				worldPoint.getY(),
				worldPoint.getPlane(),
				insideWilderness,
				insidePvpArea);
		Color othersColor = selectNameColor(
			playerInPvpZone,
			config.colorWildernessNames(),
			config.safeAreaNameColor(),
			config.wildernessNameColor());
		return getCategoryColor(player, playerInPvpZone, othersColor);
	}

	private Color getCategoryColor(Player player, boolean playerInPvpZone, Color othersColor)
	{
		Player localPlayer = client.getLocalPlayer();
		if (player == localPlayer)
		{
			return isEnabled(config.highlightOwnPlayer()) ? config.ownPlayerColor() : null;
		}

		// Read RuneLite's current party each time so joining, leaving, and member
		// login changes are reflected in names, tiles, minimap labels, and menus.
		if (isEnabled(config.highlightPartyMembers()) && partyService.isInParty() &&
			player.getName() != null && partyService.getMemberByDisplayName(player.getName()) != null)
		{
			return config.partyMemberColor();
		}

		if (player.isFriend())
		{
			Color friendColor = selectFriendColor(
				playerInPvpZone,
				config.highlightFriendsCombatZones(),
				config.friendsCombatZonesColor(),
				config.highlightFriends(),
				config.friendColor());
			if (friendColor != null)
			{
				return friendColor;
			}
		}

		if (player.isFriendsChatMember() && isEnabled(config.highlightFriendsChat()))
		{
			return config.friendsChatColor();
		}

		if (localPlayer != null && player.getTeam() > 0 &&
			player.getTeam() == localPlayer.getTeam() && isEnabled(config.highlightTeamMembers()))
		{
			return config.teamMemberColor();
		}

		if (player.isClanMember() && isEnabled(config.highlightClanMembers()))
		{
			return config.clanMemberColor();
		}

		return isEnabled(config.highlightOthers()) ? othersColor : null;
	}

	private static boolean isEnabled(PlayerIndicatorsPlusConfig.HighlightSetting setting)
	{
		return setting == PlayerIndicatorsPlusConfig.HighlightSetting.ENABLED;
	}

	static Color selectFriendColor(boolean inCombatZone,
		PlayerIndicatorsPlusConfig.HighlightSetting combatZoneSetting, Color combatZoneColor,
		PlayerIndicatorsPlusConfig.HighlightSetting normalSetting, Color normalColor)
	{
		if (inCombatZone && isEnabled(combatZoneSetting))
		{
			return combatZoneColor;
		}

		return isEnabled(normalSetting) ? normalColor : null;
	}

	FriendsChatRank getFriendsChatRank(Player player)
	{
		FriendsChatManager friendsChatManager = client.getFriendsChatManager();
		if (friendsChatManager == null)
		{
			return FriendsChatRank.UNRANKED;
		}

		FriendsChatMember member = friendsChatManager.findByName(Text.removeTags(player.getName()));
		return member == null ? FriendsChatRank.UNRANKED : member.getRank();
	}

	ClanTitle getClanTitle(Player player)
	{
		ClanChannel clanChannel = client.getClanChannel();
		ClanSettings clanSettings = client.getClanSettings();
		if (clanChannel == null || clanSettings == null)
		{
			return null;
		}

		ClanChannelMember member = clanChannel.findMember(player.getName());
		if (member == null)
		{
			return null;
		}

		ClanRank rank = member.getRank();
		return clanSettings.titleForRank(rank);
	}

	private void renderPlayerName(Graphics2D graphics, Player player, Color nameColor,
		PlayerNameLocation nameLocation)
	{
		String name = Text.sanitize(player.getName());
		int zOffset;
		switch (nameLocation)
		{
			case MODEL_CENTER:
			case MODEL_RIGHT:
				zOffset = player.getLogicalHeight() / 2;
				break;
			default:
				zOffset = player.getLogicalHeight() + OVERHEAD_TEXT_MARGIN;
		}

		Point textLocation = player.getCanvasTextLocation(graphics, name, zOffset);
		if (nameLocation == PlayerNameLocation.MODEL_RIGHT)
		{
			textLocation = player.getCanvasTextLocation(graphics, "", zOffset);
			if (textLocation != null)
			{
				textLocation = new Point(textLocation.getX() + HORIZONTAL_TEXT_MARGIN, textLocation.getY());
			}
		}

		if (textLocation == null)
		{
			return;
		}

		BufferedImage rankImage = getRankImage(player);
		if (rankImage != null)
		{
			int imageWidth = rankImage.getWidth();
			int imageTextMargin = nameLocation == PlayerNameLocation.MODEL_RIGHT ? imageWidth : imageWidth / 2;
			int imageNegativeMargin = nameLocation == PlayerNameLocation.MODEL_RIGHT ? 0 : imageWidth / 2;
			int textHeight = graphics.getFontMetrics().getHeight() - graphics.getFontMetrics().getMaxDescent();
			Point imageLocation = new Point(
				textLocation.getX() - imageNegativeMargin - 1,
				textLocation.getY() - textHeight / 2 - rankImage.getHeight() / 2);
			OverlayUtil.renderImageLocation(graphics, imageLocation, rankImage);
			textLocation = new Point(textLocation.getX() + imageTextMargin, textLocation.getY());
		}

		OverlayUtil.renderTextLocation(graphics, textLocation, name, nameColor);
	}

	private BufferedImage getRankImage(Player player)
	{
		if (player.isFriendsChatMember() && config.showFriendsChatRanks())
		{
			FriendsChatRank rank = getFriendsChatRank(player);
			if (rank != FriendsChatRank.UNRANKED)
			{
				return chatIconManager.getRankImage(rank);
			}
		}

		if (player.isClanMember() && config.showClanChatRanks())
		{
			ClanTitle title = getClanTitle(player);
			if (title != null)
			{
				return chatIconManager.getRankImage(title);
			}
		}

		return null;
	}
}

package com.playerindicatorsplus;

import com.google.inject.Provides;
import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.FriendsChatRank;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanTitle;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;

@PluginDescriptor(
	name = "Player Indicators Plus",
	description = "Highlights players with configurable names, tiles, minimap labels, ranks, and Wilderness/PvP colors",
	tags = {"wilderness", "pvp", "player", "names", "indicators", "minimap", "overlay"}
)
public class PlayerIndicatorsPlusPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PlayerIndicatorsPlusOverlay overlay;

	@Inject
	private PlayerIndicatorsPlusTileOverlay tileOverlay;

	@Inject
	private PlayerIndicatorsPlusMinimapOverlay minimapOverlay;

	@Inject
	private Client client;

	@Inject
	private ChatIconManager chatIconManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PlayerIndicatorsPlusConfig config;

	@Provides
	PlayerIndicatorsPlusConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PlayerIndicatorsPlusConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateLegacyConfig();
		overlayManager.add(overlay);
		overlayManager.add(tileOverlay);
		overlayManager.add(minimapOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(tileOverlay);
		overlayManager.remove(minimapOverlay);
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (client.isMenuOpen())
		{
			return;
		}

		int insideWilderness = client.getVarbitValue(VarbitID.INSIDE_WILDERNESS);
		int insidePvpArea = client.getVarbitValue(VarbitID.PVP_AREA_CLIENT);
		for (MenuEntry entry : client.getMenuEntries())
		{
			if (!isPlayerMenuAction(entry.getType()))
			{
				continue;
			}

			Player player = entry.getPlayer();
			if (player == null || player.getName() == null)
			{
				continue;
			}

			Color color = overlay.getPlayerColor(player, insideWilderness, insidePvpArea);
			FriendsChatRank friendsChatRank = player.isFriendsChatMember() && config.showFriendsChatRanks()
				? overlay.getFriendsChatRank(player) : null;
			ClanTitle clanTitle = player.isClanMember() && config.showClanChatRanks()
				? overlay.getClanTitle(player) : null;
			entry.setTarget(decorateTarget(entry.getTarget(), color, friendsChatRank, clanTitle));
		}
	}

	String decorateTarget(String oldTarget, Color color,
		FriendsChatRank friendsChatRank, ClanTitle clanTitle)
	{
		String newTarget = oldTarget;
		if (color != null && config.colorPlayerMenu())
		{
			String prefix = "";
			int arrowIndex = oldTarget.indexOf("->");
			if (arrowIndex != -1)
			{
				prefix = oldTarget.substring(0, arrowIndex + 3);
				oldTarget = oldTarget.substring(arrowIndex + 3);
			}

			int tagEnd = oldTarget.indexOf('>');
			if (oldTarget.startsWith("<col=") && tagEnd != -1)
			{
				oldTarget = oldTarget.substring(tagEnd + 1);
			}
			newTarget = prefix + ColorUtil.prependColorTag(oldTarget, color);
		}

		int image = -1;
		if (friendsChatRank != null && friendsChatRank != FriendsChatRank.UNRANKED &&
			config.showFriendsChatRanks())
		{
			image = chatIconManager.getIconNumber(friendsChatRank);
		}
		else if (clanTitle != null && config.showClanChatRanks())
		{
			image = chatIconManager.getIconNumber(clanTitle);
		}

		return image == -1 ? newTarget : "<img=" + image + ">" + newTarget;
	}

	private static boolean isPlayerMenuAction(MenuAction action)
	{
		switch (action)
		{
			case WALK:
			case WIDGET_TARGET_ON_PLAYER:
			case ITEM_USE_ON_PLAYER:
			case PLAYER_FIRST_OPTION:
			case PLAYER_SECOND_OPTION:
			case PLAYER_THIRD_OPTION:
			case PLAYER_FOURTH_OPTION:
			case PLAYER_FIFTH_OPTION:
			case PLAYER_SIXTH_OPTION:
			case PLAYER_SEVENTH_OPTION:
			case PLAYER_EIGHTH_OPTION:
			case RUNELITE_PLAYER:
				return true;
			default:
				return false;
		}
	}

	private void migrateLegacyConfig()
	{
		Boolean showOwnName = configManager.getConfiguration(
			PlayerIndicatorsPlusConfig.GROUP, "showOwnName", Boolean.class);
		if (showOwnName == null)
		{
			return;
		}

		if (configManager.getConfiguration(
			PlayerIndicatorsPlusConfig.GROUP, "highlightOwnPlayer") == null)
		{
			PlayerIndicatorsPlusConfig.HighlightSetting setting = showOwnName
				? PlayerIndicatorsPlusConfig.HighlightSetting.ENABLED
				: PlayerIndicatorsPlusConfig.HighlightSetting.DISABLED;
			configManager.setConfiguration(
				PlayerIndicatorsPlusConfig.GROUP, "highlightOwnPlayer", setting);
		}
		configManager.unsetConfiguration(PlayerIndicatorsPlusConfig.GROUP, "showOwnName");
	}
}

package com.playerindicatorsplus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

@Singleton
class PlayerIndicatorsPlusTileOverlay extends Overlay
{
	private final Client client;
	private final PlayerIndicatorsPlusConfig config;
	private final PlayerIndicatorsPlusOverlay playerNamesOverlay;

	@Inject
	private PlayerIndicatorsPlusTileOverlay(Client client, PlayerIndicatorsPlusConfig config,
		PlayerIndicatorsPlusOverlay playerNamesOverlay)
	{
		this.client = client;
		this.config = config;
		this.playerNamesOverlay = playerNamesOverlay;
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN || !config.drawTiles())
		{
			return null;
		}

		WorldView topLevelWorldView = client.getTopLevelWorldView();
		if (topLevelWorldView == null)
		{
			return null;
		}

		int insideWilderness = client.getVarbitValue(VarbitID.INSIDE_WILDERNESS);
		int insidePvpArea = client.getVarbitValue(VarbitID.PVP_AREA_CLIENT);
		renderWorldView(graphics, topLevelWorldView, insideWilderness, insidePvpArea);
		for (WorldView worldView : topLevelWorldView.worldViews())
		{
			renderWorldView(graphics, worldView, insideWilderness, insidePvpArea);
		}

		return null;
	}

	private void renderWorldView(Graphics2D graphics, WorldView worldView,
		int insideWilderness, int insidePvpArea)
	{
		if (worldView == null)
		{
			return;
		}

		for (Player player : worldView.players())
		{
			if (player == null || player.getName() == null)
			{
				continue;
			}

			LocalPoint localPoint = player.getLocalLocation();
			if (localPoint == null || !worldView.contains(localPoint))
			{
				continue;
			}

			Color color = playerNamesOverlay.getPlayerColor(player, insideWilderness, insidePvpArea);
			Polygon tile = player.getCanvasTilePoly();
			if (color != null && tile != null)
			{
				OverlayUtil.renderPolygon(graphics, tile, color);
			}
		}
	}
}

